import{c as t,Q as n,j as a,m as o}from"./chunks/framework.BXc4yaFE.js";const p=JSON.parse('{"title":"Invasive Context Engineering to Control Large Language Models","description":"","frontmatter":{"url":"https://arxiv.org/abs/2512.03001","title":"Invasive Context Engineering to Control Large Language Models","archived_date":"2026-06-24T00:00:00.000Z","arxiv_id":2512.03001,"authors":["Thomas Rivasseau"],"domains":["cs.AI","context engineering"],"html":"https://arxiv.org/html/2512.03001v1","pdf_path":"pdfs/2512.03001.pdf","published_date":"2025-12-02T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2025-12-02-invasive-context-engineering-2512-03001.md","filePath":"research/papers/2025-12-02-invasive-context-engineering-2512-03001.md","lastUpdated":1785909234000}'),r={name:"research/papers/2025-12-02-invasive-context-engineering-2512-03001.md"};function i(s,e,l,g,c,h){return n(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="invasive-context-engineering-to-control-large-language-models" tabindex="-1">Invasive Context Engineering to Control Large Language Models <a class="header-anchor" href="#invasive-context-engineering-to-control-large-language-models" aria-label="Permalink to &quot;Invasive Context Engineering to Control Large Language Models&quot;">​</a></h1><p><strong>Authors</strong>: Thomas Rivasseau <strong>Published</strong>: December 02, 2025 <strong>Source</strong>: <a href="https://arxiv.org/abs/2512.03001" target="_blank" rel="noreferrer">https://arxiv.org/abs/2512.03001</a> · <a href="https://arxiv.org/html/2512.03001v1" target="_blank" rel="noreferrer">HTML</a><strong>arXiv ID</strong>: 2512.03001 <strong>Categories</strong>: cs.AI <strong>PDF</strong>: <a href="https://arxiv.org/abs/2512.03001" target="_blank" rel="noreferrer">research/papers/pdfs/2512.03001.pdf</a> (4 pp, full text archived)</p><hr><h2 id="abstract-quoted" tabindex="-1">Abstract (quoted) <a class="header-anchor" href="#abstract-quoted" aria-label="Permalink to &quot;Abstract (quoted)&quot;">​</a></h2><blockquote><p>Current research on operator control of Large Language Models improves model robustness against adversarial attacks and misbehavior by training on preference examples, prompting, and input/output filtering. Despite good results, LLMs remain susceptible to abuse, and jailbreak probability increases with context length. There is a need for robust LLM security guarantees in long-context situations. We propose control sentences inserted into the LLM context as invasive context engineering to partially solve the problem. We suggest this technique can be generalized to the Chain-of-Thought process to prevent scheming. Invasive Context Engineering does not rely on LLM training, avoiding data shortage pitfalls which arise in training models for long context situations.</p></blockquote><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h3><ul><li>提出 <strong>Invasive Context Engineering</strong>：在 LLM 的 context 中插入控制句（control sentences），作為無需重新訓練的安全強化手段。</li><li>識別一個已知問題：context 越長，jailbreak 成功率越高；現有 training-based 方法在長 context 場景資料不足。</li><li>主張此技術可推廣至 <strong>Chain-of-Thought (CoT)</strong> 過程，用以防止模型 scheming（策略性欺騙）行為。</li><li>方法與訓練解耦，規避長 context 訓練資料匱乏的瓶頸。</li></ul><h3 id="關鍵結果" tabindex="-1">關鍵結果 <a class="header-anchor" href="#關鍵結果" aria-label="Permalink to &quot;關鍵結果&quot;">​</a></h3><ul><li>論文為 4 頁短論文（workshop paper 規模），以概念性論證為主，未提供大規模量化評估數字。</li><li>核心宣稱：在 context 內插入控制句可「部分解決」長 context 下的安全控制問題。</li><li>CoT 推廣方向屬初步提案，缺乏實驗驗證。</li></ul><h3 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h3><ul><li>論文未列獨立 limitation 章節；判斷弱點： <ol><li>4 頁篇幅，缺乏系統性實驗（無 benchmark、無對照組數字）。</li><li>「部分解決」措辭模糊，未定義解決程度或失效條件。</li><li>Invasive context sentences 本身可能被 adversarial prompt 覆蓋或稀釋（injection 攻擊反制）。</li><li>CoT 推廣至 anti-scheming 的可行性僅為推測，未驗證。</li></ol></li></ul><hr><h2 id="workspace-關聯-評估-非既成結論" tabindex="-1">Workspace 關聯（評估，非既成結論） <a class="header-anchor" href="#workspace-關聯-評估-非既成結論" aria-label="Permalink to &quot;Workspace 關聯（評估，非既成結論）&quot;">​</a></h2><ul><li><strong>直接對應 core.md「判斷 vs 決定」跨切紀律</strong>：本文的 control sentences 類似在 context 中強制插入確定性語義錨點，與「確定性代碼做決定，LLM 只做判斷」原則呼應——但本文方案仍依賴 LLM 解讀控制句，可靠性未達確定性代碼層級。⚠️ 落地門檻：需在實際 prompt pipeline 驗證控制句不被後續輸入覆蓋。</li><li><strong>呼應 context-management.md NLAH 原則</strong>（Right context &gt; more context）：本文指出 context 越長安全性越低，與 workspace 限制 context rot、偏好精簡 context 的方向一致；control sentences 的「HEAD/TAIL 錨定」策略值得參考。</li><li><strong>與 <code>core.md §PROPOSE 委派</code>（原 subagent-strategy.md） Agent Input Security 對齊</strong>：workspace 規則要求外部輸入包裹 <code>&lt;untrusted_objective&gt;</code> 標籤，本文 invasive context engineering 提供了類似的 context-level isolation 思路，可作為 multi-agent prompt injection 防禦的參考框架。⚠️ 機制差異大，不可直接套用。</li><li><strong>anti-scheming CoT 段落與 The Loop unverified_success 閘門相關</strong>：workspace 規定 subagent 自報「成功」= 中間態，需主對話親跑確定性檢查；本文防止 CoT scheming 的動機與此閘門的設計意圖同源——均在對抗 LLM 自利性輸出，但本文方法尚未驗證，不宜直接採信。</li></ul>',16)])])}const u=t(r,[["render",i]]);export{p as __pageData,u as default};
